package com.hospital.smartqueue.hospital.api;
import com.hospital.smartqueue.hospital.application.HospitalService; import jakarta.validation.constraints.NotBlank; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/hospitals") public class HospitalController { private final HospitalService service; public HospitalController(HospitalService s){service=s;} public record NameRequest(@NotBlank String name){} public record HospitalResponse(UUID id,String name){} public record BranchResponse(UUID id,UUID hospitalId,String name){}
 @PostMapping public ResponseEntity<HospitalResponse> create(@RequestBody @jakarta.validation.Valid NameRequest r){var h=service.createHospital(r.name());return ResponseEntity.status(HttpStatus.CREATED).body(new HospitalResponse(h.getId(),h.getName()));} @GetMapping public List<HospitalResponse> list(){return service.listHospitals().stream().map(h->new HospitalResponse(h.getId(),h.getName())).toList();}
 @PostMapping("/{hospitalId}/branches") public ResponseEntity<BranchResponse> branch(@PathVariable UUID hospitalId,@RequestBody @jakarta.validation.Valid NameRequest r){var b=service.createBranch(hospitalId,r.name());return ResponseEntity.status(HttpStatus.CREATED).body(new BranchResponse(b.getId(),b.getHospitalId(),b.getName()));} @GetMapping("/{hospitalId}/branches") public List<BranchResponse> branches(@PathVariable UUID hospitalId){return service.listBranches(hospitalId).stream().map(b->new BranchResponse(b.getId(),b.getHospitalId(),b.getName())).toList();}}
